/** The disclosure for a set of films: one line when they share it, otherwise the most cautious one. */
export function disclosureFor(films) {
  const lines = [...new Set(films.map((f) => DISCLOSURE[f.origin] || DISCLOSURE.unconfirmed))];
  return lines.length === 1 ? lines[0] : DISCLOSURE.unconfirmed;
}
